{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "The closest scaffold analogue Lu 3-009, which shares the same CCCC-bridge and gem-dimethyl heterocycle but has O instead of S and an N-methyl instead of NH, showed brain/blood ratios of 2.8 at 15 min and 3.6 at 60 min in rats, demonstrating meaningful CNS access despite a basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Desipramine, a secondary amine tricyclic antidepressant with a similar basic side chain, had a rat brain perfusion uptake rate of 16.92 pmol/g/s/µM and is classified as CNS-positive, supporting that such lipophilic basic amines can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In humans, ketamine reached a CSF:plasma ratio of 0.917, directly showing that a basic amine with transporter/efflux potential can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "After i.v. dosing in rats, (R)-ketamine achieved brain tissue to plasma concentration ratios of 4.8–10.5, confirming rapid and substantial BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The nisoxetine analogue [125I]2-INXT showed good initial brain uptake (0.56% dose at 2 min) in rats, with transporter-mediated uptake, indicating that lipophilic basic amines can achieve CNS access even when transport is involved.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer direct in vivo measurements in closely related lipophilic basic amines—including the closest scaffold analogue Lu 3-009—demonstrate meaningful brain/plasma or CSF exposure after systemic administration. The physicochemical prior of low passive diffusion and possible efflux is outweighed by this direct experimental evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule",
    "Exact P-gp/BCRP efflux liability of the thioether analogue is not directly measured",
    "Unbound brain concentrations and transporter dependence are not quantified",
    "Longer time-point brain exposure for the query scaffold is limited; Lu 3-009 declined by 240 min"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

